[{"order":1,"type":"heading","text":"Mastering Eloquent Relationships in Laravel"},{"order":2,"type":"paragraph","text":"Eloquent ORM in Laravel makes interacting with your database feel effortless. Understanding database relationships is crucial for building robust applications. This tutorial covers One-to-One, One-to-Many, Many-to-Many, and Polymorphic relationships with practical implementation examples."},{"order":3,"type":"subheading","text":"1. One-to-One Relationship"},{"order":4,"type":"paragraph","text":"A One-to-One relationship is a basic relation. For example, a User model might be associated with one Profile model. To define this, use the hasOne and belongsTo methods."},{"order":5,"type":"code","text":"public function profile() {
    return $this->hasOne(Profile::class);
}

public function user() {
    return $this->belongsTo(User::class);
}"},{"order":6,"type":"subheading","text":"2. One-to-Many Relationship"},{"order":7,"type":"paragraph","text":"A One-to-Many relationship is used to define relationships where a single model owns any amount of other models. For instance, a Post can have many Comments."},{"order":8,"type":"code","text":"public function comments() {
    return $this->hasMany(Comment::class);
}

public function post() {
    return $this->belongsTo(Post::class);
}"},{"order":9,"type":"subheading","text":"3. Many-to-Many Relationship"},{"order":10,"type":"paragraph","text":"Many-to-Many relations are more complicated than 'hasOne' and 'hasMany'. An example of this is a User that has many roles, and the roles are also shared by other users. This requires an intermediate pivot table."},{"order":11,"type":"code","text":"public function roles() {
    return $this->belongsToMany(Role::class);
}

public function users() {
    return $this->belongsToMany(User::class);
}"},{"order":12,"type":"subheading","text":"4. Polymorphic Relationships"},{"order":13,"type":"paragraph","text":"Polymorphic relationships allow a target model to belong to more than one type of model on a single association. For example, both Posts and Videos can share a polymorphic relation with a Comment model."},{"order":14,"type":"code","text":"public function commentable() {
    return $this->morphTo();
}

public function comments() {
    return $this->morphMany(Comment::class, "commentable");
}"},{"order":15,"type":"bullet_point","text":"Always define inverse methods to ensure seamless querying."},{"order":16,"type":"bullet_point","text":"Use eager loading (with method) to avoid the N+1 query problem."},{"order":17,"type":"bullet_point","text":"Ensure proper foreign keys and indexes are set up in your database migrations."}]
